guidance.correct_example:
@dataclass
class UserProfile:
    name: str
    email: str
    role: str

def get_profile(a_id: int) -> Result[UserProfile]:
    user = db.query(a_id)
    if user is None:
        return Result.failure(f'User {a_id} not found')
    profile = UserProfile(name=user.name, email=user.email, role=user.role)
    return Result.success(profile)

guidance.incorrect_example:
def get_profile(a_id: int) -> tuple[str, str, str]:
    user = db.query(a_id)
    return (user.name, user.email, user.role)
